R=Path(__file__).parent
resources=[
 dict(id='guide',title='Your Data Engineering & MLOps roadmap',type='Course guide',format='PDF',desc='A flexible learning map, study approach and practical project milestones.',url='resources/course-guide.pdf',document='guide'),
 dict(id='study',title='The complete study companion',type='Study notes',format='PDF',desc='Twenty focused lessons with worked examples, reflection prompts and a concise glossary.',url='resources/study-companion.pdf',document='study'),
 dict(id='workbook',title='Build your MLOps project',type='Projects',format='PDF',desc='Plan a pipeline and evaluate an MLOps tool with step-by-step worksheets.',url='resources/project-workbook.pdf',document='workbook'),
 dict(id='quizbook',title='50 questions to connect the ideas',type='Practice',format='PDF',desc='Ten questions per module with a complete explained answer key for offline revision.',url='resources/quiz-workbook.pdf',document='quizbook')]
videos=[
 ('etl','ETL vs ELT: Powering Data Pipelines for AI & Analytics','IBM Technology','KIv2Na2-u24',1,'Compare when transformation happens and how that affects your pipeline design.','What would make you transform data before loading it?'),
 ('lake','What is a Data Lake?','IBM Technology','LxcH6z8TFpI',2,'Explore a data-lake architecture and how raw data becomes useful for analysis.','What metadata and quality controls would keep your lake usable?'),
 ('micro','What are Microservices?','IBM Technology','CdBtNQZH8a4',2,'Compare a service-based architecture with a traditional monolith.','Which boundary could your team own and deploy independently?'),
 ('mlops','What is MLOps?','IBM Technology','OejCJL2EC3k',3,'Connect model development with automation and operations.','Which risks remain after a model has been trained successfully?'),
 ('cloud','An introduction to MLOps on Google Cloud','Google Cloud Tech','6gdrwFMaEZ0',4,'See a production ML lifecycle through a cloud-platform example.','Which parts of this lifecycle apply even if you use a different platform?'),
 ('tracking','MLflow 3.0: AI and MLOps on Databricks','Databricks','UezTglxJC88',3,'Explore experiment tracking, model lifecycle management and deployment workflows.','What evidence would you retain to compare two candidate models?'),
 ('best','MLOps Best Practices on Google Cloud','Google Cloud Tech','20h_RTHEtZI',4,'A conference session linked from Google Cloud’s MLOps architecture guide.','Where would you place validation and promotion gates in your own design?'),
 ('governance','Data Governance Explained in 5 Minutes','IBM Technology','uPsUjKLHLAg',5,'Connect data ownership, access and governance with reliable use.','Who owns each dataset and model decision in your project?')]
for id,title,creator,vid,module,desc,prompt in videos:
 resources.append(dict(id=id,title=title,type='Video',format='VIDEO',desc=desc,url='https://www.youtube.com/watch?v='+vid,video=vid,creator=creator,module=module,prompt=prompt))
readings=[
 ('data-brief','What makes data useful?','IBM','https://www.ibm.com/think/topics/data-engineering',1,[
 ('Start with the consumer','A pipeline is useful when people can rely on its outputs for a decision. Define the required dataset, its meaning and the time by which it should arrive before choosing tools.'),('Think across stages','Source collection, transformation and serving are connected. A clean transformation cannot rescue an incorrectly defined source or an output nobody understands. Record lineage and ownership through the flow.'),('Try it','Choose a daily sales report. Write its freshness target, key fields and the person who resolves a failed delivery.')]),
 ('architecture','Service boundaries and trade-offs','James Lewis & Martin Fowler','https://martinfowler.com/articles/microservices.html',2,[
 ('A boundary is a commitment','A service should have a clear purpose and interface. Independence is useful only when a team can build, release and operate the component responsibly.'),('Count the costs','Network calls, partial failures, debugging and cross-service data consistency add work. Compare those costs with the value of independent changes and scaling.'),('Try it','Draw two components for a retailer and identify the interface between them. Explain one failure that should not stop the other component.')]),
 ('airflow','Orchestration as a dependency graph','Apache Airflow','https://airflow.apache.org/docs/apache-airflow/stable/core-concepts/overview.html',2,[
 ('Describe the dependencies','A workflow graph records which tasks must finish before others begin. For example, validate an ingested partition before publishing the transformed table.'),('Task success is not data correctness','An orchestrator tracks execution, but your tasks must check the data they publish. Retries also need safe write behavior to avoid duplicated output.'),('Try it','Draw extract, validate, transform and publish as a directed acyclic graph. Add the action to take when validation fails.')]),
 ('tracking-brief','A useful experiment record','MLflow','https://www.mlflow.org/docs/latest/tracking/',3,[
 ('Connect inputs and evidence','Record the code and data identifiers, environment, configuration, evaluation metrics and output files for each run. Use consistent naming so comparisons answer a clear question.'),('Separate the record types','Parameters describe settings. Metrics hold measurements. Artifacts preserve files such as plots or models. Tracking helps review an experiment; it does not prove the experiment was designed correctly.'),('Try it','Specify two runs that change one parameter while keeping the evaluation split fixed. Name the metric and artifacts you would compare.')]),
 ('leakage','Keep evaluation data out of training decisions','scikit-learn','https://scikit-learn.org/stable/common_pitfalls.html',3,[
 ('Split before learning transformations','Learn scaling or imputation statistics from the training data. Apply those learned operations to held-out data without fitting them again.'),('Check prediction-time availability','A field can be accurate and still leak the future. Exclude information recorded after the point where the real system must make a prediction.'),('Try it','For a churn model, compare last month’s usage with a cancellation date recorded after the prediction. Explain which field leaks the outcome.')]),
 ('delivery','Build a delivery loop for ML','Google Cloud','https://docs.cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning',4,[
 ('Automate a tested path','Connect changes to repeatable checks, training, evaluation and artifact creation. Keep evidence for the candidate that passes the gates.'),('Distinguish the loops','Software delivery changes the implementation. Retraining updates a model with data. Both require validation, traceability and an appropriate promotion decision.'),('Try it','Sketch a path from a code commit to a staged model, then draw a separate retraining trigger that reuses the same evaluation gate.')]),
 ('monitoring','Investigate a drift signal','Google Cloud','https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/model-monitoring/overview',5,[
 ('Name the reference','A distribution comparison only makes sense against a documented baseline and observation window. Track changes in inputs separately from confirmed changes in outcomes.'),('Investigate before retraining','A broken data transformation and a changing user population can both shift input statistics. Check quality and context, then use outcome evidence when available.'),('Try it','Write a missing-value alert with an owner, first diagnostic step and follow-up metric. Decide what evidence would justify retraining.')])]
for id,title,creator,url,module,sections in readings:
 resources.append(dict(id=id,title=title,type='Reading',format='STUDY BRIEF',desc='Read an original study brief in the studio, then explore the source for more detail.',creator=creator,url=url,module=module,sections=[dict(title=t,body=b) for t,b in sections]))
(R/'dist/resources.json').write_text(json.dumps(resources,ensure_ascii=False,indent=2))
